        "summary": "“平安大姐”是“中国童装之都”——吴兴区织里镇的一群女性志愿者。她们来自17个省24个地区，不仅无偿开展矛盾纠纷化解、观护帮教、法治宣传等志愿服务，还自掏腰包进行公益资助，成为基层治理的重要力量。十年来，大姐们接待来访群众33000余人，化解纠纷2280余起，解决率达98.3% ，挽回经济损失达2.4余亿元。\n“平安大姐”团队的带头人是一名党员，名叫徐维丽。2003年，因为看中了织里浓厚的创业氛围，徐维丽举家从辽宁海城到织里经营童装生意。2015年，徐维丽和其他14名在织里打拼的小姐妹，一起成立了“平安大姐”社会工作室，主要为新居民朋友化解矛盾纠纷、困难帮扶。2019年，成立了湖州安姐职业培训学院，将学院利润大部分用于志愿服务，实现了社会组织开展志愿服务的自我造血。"
