        "summary": "喻家台社区位于园林城区中心，成立于2003年，面积1.98平方公里，共有常住户2572户7254人，属于大型社区，辖区内有13家机关、企事业单位。社区科普活动站成立于2011年，现有7名专兼职科普工作人员，有一支23人组成的科普志愿者队伍。社区设有一站式服务大厅，科普益民服务站、科普书屋、科普画廊、LED电子屏幕、投影机、电脑等科普硬件设施。社区现有室内科普活动场所60㎡、科普宣传栏12平方米、科普图书1933册、科普展板19块、电脑投影仪1台等科普设备。\n社区在创建“科普示范社区”的基础上，进一步建立健全社区科普组织网络。完善科普工作领导小组，以社区书记牵头负总责、社区其他干部成员共同参与实施的科普工作机制；充实壮大“科普志愿者服务队伍”，以科普志愿者带动周边社区群众树立崇尚科学破除迷信的决心与信心；并依托辖区内企事业单位及共建单位，由社区牵头组织邀请卫生、文化、科技、教育等多方面专家、学者，深入到社区及社区居民家中开展多样、生动活泼的科普文化宣传及文娱活动。\n凭借扎实的工作成效，2015年3月获评“全国科普示范社区”的称号。喻家台社区坐落于潜江市园林办事处西南，东起园林路、南接长渠路、西临百里长渠、北靠潜阳中路，辖区面积 1.98 平方公里，常住人口 7540 人，涵盖 13 个单位及10 个居民小区。多年来，社区深耕“民主法治示范社区”创建工作。\n以“法制宣传教育和人民调解文化社区行”为抓手，通过健全党员干部学法制度、开展法律讲座、设置宣传橱窗、增补普法读物等举措，搭配法律知识抢答赛、调解文化作品展示等文娱活动，让普法教育融入日常生活，实现常态化、通俗化。同时，以社会管理创新和分级联动调解为保障，构建 “社区搭台、部门唱戏” 的联动模式，依托网格化管理整合维稳资源，形成多方参与的大调解格局，做到有案必受、有受必理、有理必果、有果必公，矛盾纠纷调处率达 98%，调处成功率超 90%。\n凭借扎实成效，2015年3月获评“全国民主法治示范社区”称号。"
