        "summary": "青和居社区位于工人村街道西部，辖区居民5235户、6100余人，是全市规模最大的公租房小区，老年人多、困难人群多、残疾朋友多。社区党委下辖15个党支部，直管党员116人。现有社区工作者28名，其中社区“两委”8名。\n2018年4月26日，习近平总书记到青和居社区视察，对社区党建引领基层社会治理做法给予高度肯定，特别指出社区党组织在领导社区治理方面创造了许多新鲜经验，比如，以党建引领物业服务创新、“三治一服务”理念、“天天敲门十八法”等效果很好、深受群众欢迎，值得总结和推广。\n近年来，青和居社区认真贯彻落实习近平总书记重要指示精神，深化党组织领导下的“三治一服务”体系，建强扎深“社区党委—片区党总支—楼栋党支部—党员中心户”组织体系，优化完善治理体系，做精做细服务体系，拓展“天天敲门组”“顺顺吧”“社区好味到大食堂”“四点半学校”等服务载体，扎实开展基层治理创新，努力构建共治共享的治理格局。社区先后荣获全国先进基层党组织、全国抗击新冠肺炎疫情先进集体、全国文明单位、全国119消防先进集体、全国最美志愿服务社区、全国示范性老年友好型社区、全国爱国卫生运动70周年先进集体等荣誉。"
