        "summary": "灵山县三海街道三海社区于2021年1月由原三海村改制设立，位于灵山县城西郊，辖区面积约7.5平方公里，现有居民5752户、23618人。社区以建设老年友好型社区为目标，系统推进公共空间与老年人家庭适老化改造，显著提升居住安全与生活便利性。通过整合辖区养老、医疗及文化资源，以社区老年活动中心为核心阵地，常态化开展健康体检、文化娱乐等精准化服务。积极搭建“老有所为”平台，培育多支老年文体团队，组建“银龄”志愿服务队，引导老年人主动参与矛盾调解等社区治理事务，全方位营造敬老、助老、用老的浓厚社会氛围。2024年1月，被国家卫生健康委员会、全国老龄工作委员会办公室授予“全国示范性老年友好型社区”；2024年11月，被广西壮族自治区民政厅、住房和城乡建设厅授予“AAA”级广西老年人宜居社区。"
