        "summary": "富文社区常住人口3218户8463人，总面积约1.6万平方公里，共有住宅楼88幢。富文社区人民调解委员会始终坚持和发展新时代“枫桥经验”，锚定“小事不出居、大事不出街、矛盾不上交”目标，全面落实“五有、四落实、六统一”标准，现有调解员8名，其中专职调解员2名、党员4名，以过硬作风和创新举措筑牢基层稳定防线，于2020年12月获评“全国模范人民调解委员会”荣誉称号。\n健全三级联动化解体系，构建“社区—网格——楼栋”三级调解网络，辖区共划分27个网格，实现矛盾纠纷“网中排查、格中化解”。近三年累计排查矛盾纠纷161件，成功化解154件，调解成功率达95%以上，无因调解不及时引发的刑事案件、群体性事件及重大信访投诉。\n坚持调解普法相融互促，通过“近邻帮帮团”、“近邻恳谈会”、“以案释法”等形式，向群众普及《民法典》、《人民调解法》等法律法规，组建法治宣传志愿服务队，开展法治汇演、入户宣讲48场次，发放宣传资料4000余份，引导群众遇事找法、办事依法。"
