        "summary": "红旗社区位于铜川市王益区中心地段，总面积0.4平方公里，下辖23个居民小区，15家企事业单位，服务群众4741户10371人。为提升基层治理水平，近年来，红旗社区党委主动顺应城市基层治理的新形势和新要求，以群众的呼声为第一信号、群众的需求为第一选择、群众的满意为第一标准，经过多年探索，逐渐形成了以“网格化管理、智慧化服务、联动式共建”为主要内容的“红旗经验”，走出了一条“党建领航、贴心为民、创新服务、头雁引领、多方联动”的城市基层党建引领社会治理的新路径。\n红旗社区突出“便民、利民、亲民”主题,不断探索创新社区征询民意的方法途径，社区“3+3+X”服务模式得到了社会的认可，赢得了百姓的赞许。按照业缘、趣缘、地缘等要素，广泛组建医疗救助、物业服务、家政服务等社会组织，孵化壮大社区服务组织有序参与基层治理，同时积极动员组织辖区单位、社会组织、物业公司等参与法治宣传、安全防范、民事调解等工作，组织居民和志愿者组成“红袖章”巡逻队，加强护楼、护院和治安巡逻，共同维护社区和谐稳定。红旗社区先后荣获“全国和谐社区建设示范社区”、全国民主法治示范社区、全国三八红旗集体、全国模范人民调解委员会等90余项荣誉称号。"
