        "summary": "尧都区铁路东街道三元社区辖区面积1.5平方公里，辖20个小区，常住人口7023户21069人。社区党委下设5个直属党支部、20个小区党支部，共有居民党员358名（其中离退休党员239名、流动党员28名），报到单位24个、在职党员906名。 三元社区聚焦老旧小区治理痛点，推行“1235”治理模式：“1” 抓牢党建引领核心，建强四级组织架构，落实“四双”机制，深化党建联建；“2” 推动小区自治与网格共治双向发力，构建“一核多元”格局；“3” 健全三项长效机制，形成治理闭环；“5” 统筹五支骨干队伍，激发治理活力，持续提升居民幸福感、获得感、安全感。社区于2017年2月被中宣部授予“全国学雷锋志愿服务‘四个100’最美志愿服务社区”；于2021年6月28日，在中国共产党成立100周年之际，被中共中央授予“全国先进基层党组织”荣誉称号；于2021年12月，被平安中国建设协调小组评为“平安中国建设先进集体”荣誉；于2025年5月，被中央宣传思想文化工作领导小组授予“全国文明单位”称号；于2025年9月，被中共山西省纪律检查委员会、山西省监察委员会、中共山西省委社会工作部、山西省民政厅授予“清廉村居建设示范单位”等181项荣誉。"
